"""Budgets: spending limits per calendar period and how a stretch of time measures against them."""

import calendar
import re
from dataclasses import dataclass
from datetime import date, datetime, timedelta
from decimal import Decimal
from fractions import Fraction
from typing import Tuple

from tallybook.errors import ValidationError
from tallybook.money import Money, round_div

PERIOD_KINDS = ("month", "quarter", "year")
_SEGMENT = re.compile(r"[A-Z][A-Za-z0-9_-]*")


class BudgetError(ValidationError):
    """A budget or a budget request that is not valid."""


def _is_date(value):
    return isinstance(value, date) and not isinstance(value, datetime)


def _check_pattern(pattern):
    if not isinstance(pattern, str) or not pattern:
        raise BudgetError("invalid budget pattern %r: must be non-empty text" % (pattern,))
    for segment in pattern.split(":"):
        if segment != "*" and not _SEGMENT.fullmatch(segment):
            raise BudgetError(
                "invalid budget pattern %r: segments are account names or '*'" % (pattern,))


@dataclass(frozen=True)
class Budget:
    """How much may be spent on the accounts of ``pattern`` in each calendar period."""

    pattern: str
    period_kind: str
    amount: Money
    start: date

    def __post_init__(self):
        _check_pattern(self.pattern)
        if not isinstance(self.period_kind, str) or self.period_kind not in PERIOD_KINDS:
            raise BudgetError("invalid period kind %r: must be month, quarter or year"
                              % (self.period_kind,))
        if not isinstance(self.amount, Money):
            raise BudgetError("budget amount must be a Money, not %r" % (self.amount,))
        if self.amount.minor <= 0:
            raise BudgetError("budget amount must be greater than zero, not %s" % (self.amount,))
        if not _is_date(self.start):
            raise BudgetError("budget start must be a date, not %r" % (self.start,))


@dataclass(frozen=True)
class BudgetLine:
    """One budget measured over one period."""

    pattern: str
    period_kind: str
    budget: Money
    actual: Money
    remaining: Money
    percent: Decimal
    over: bool
    accounts: Tuple[Tuple[str, Money], ...]

    def to_dict(self):
        return {
            "pattern": self.pattern,
            "period_kind": self.period_kind,
            "budget": _money_dict(self.budget),
            "actual": _money_dict(self.actual),
            "remaining": _money_dict(self.remaining),
            "percent": str(self.percent),
            "over": self.over,
            "accounts": [{"account": path, "amount": _money_dict(amount)}
                         for path, amount in self.accounts],
        }


def _money_dict(money):
    return {"amount": money.amount_str(), "currency": money.currency}


def _calendar_period(kind, day):
    """First and last day of the calendar month, quarter or year containing ``day``."""
    if kind == "year":
        return date(day.year, 1, 1), date(day.year, 12, 31)
    width = 1 if kind == "month" else 3
    first_month = ((day.month - 1) // width) * width + 1
    last_month = first_month + width - 1
    return (date(day.year, first_month, 1),
            date(day.year, last_month, calendar.monthrange(day.year, last_month)[1]))


def _allowance(budget, period):
    """The budget amount prorated over ``period``, or None when it is not in force there."""
    first_start, _ = _calendar_period(budget.period_kind, budget.start)
    if first_start > period.end:
        return None
    cursor = max(period.start, first_start)
    total = Fraction(0)
    while cursor <= period.end:
        cal_start, cal_end = _calendar_period(budget.period_kind, cursor)
        overlap = (min(period.end, cal_end) - max(period.start, cal_start, first_start)).days + 1
        total += Fraction(overlap, (cal_end - cal_start).days + 1)
        if cal_end == date.max:
            break
        cursor = cal_end + timedelta(days=1)
    scaled = total * budget.amount.minor
    return Money(round_div(scaled.numerator, scaled.denominator), budget.amount.currency)


def _matches(pattern_segments, path):
    parts = path.split(":")
    if parts[0] != "Expenses" or len(parts) < len(pattern_segments):
        return False
    return all(p == "*" or p == part for p, part in zip(pattern_segments, parts))


def _percent(actual, allowance):
    if allowance.minor == 0:
        return Decimal("0.0") if actual.minor == 0 else Decimal("100.0")
    tenths = round_div(actual.minor * 1000, allowance.minor)
    digits = tuple(int(c) for c in str(abs(tenths)))
    return Decimal((1 if tenths < 0 else 0, digits, -1))


def budget_status(budgets, ledger, period):
    """Measure each budget in force over ``period`` against the postings of ``ledger``."""
    postings = [(posting.account, posting.amount)
                for tx, posting in ledger.postings()
                if period.start <= tx.date <= period.end and posting.amount is not None]
    order = {kind: i for i, kind in enumerate(PERIOD_KINDS)}
    lines = []
    for budget in sorted(budgets, key=lambda b: (b.pattern, order[b.period_kind], b.start)):
        allowance = _allowance(budget, period)
        if allowance is None:
            continue
        segments = budget.pattern.split(":")
        currency = budget.amount.currency
        per_account = {}
        for account, amount in postings:
            if amount.currency == currency and _matches(segments, account):
                per_account[account] = per_account.get(account, 0) + amount.minor
        actual = Money(sum(per_account.values()), currency)
        accounts = tuple((path, Money(minor, currency))
                         for path, minor in sorted(per_account.items()) if minor != 0)
        lines.append(BudgetLine(
            pattern=budget.pattern,
            period_kind=budget.period_kind,
            budget=allowance,
            actual=actual,
            remaining=allowance - actual,
            percent=_percent(actual, allowance),
            over=actual > allowance,
            accounts=accounts,
        ))
    return lines

