"""Recurring transactions: plain-word schedules and dated copies of a template."""

import calendar
import re
from dataclasses import dataclass
from datetime import date, datetime, timedelta
from itertools import islice
from typing import Optional

from tallybook.errors import ValidationError
from tallybook.model import Transaction

WEEKDAYS = ("mon", "tue", "wed", "thu", "fri", "sat", "sun")
WEEKDAY_NAMES = ("Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday")
MONTH_NAMES = ("January", "February", "March", "April", "May", "June", "July", "August",
               "September", "October", "November", "December")
UNITS = ("day", "week", "month", "year")
MAX_STEP_DIGITS = 4000

SHAPES = ("daily", "weekly on mon|tue|wed|thu|fri|sat|sun", "monthly on 1..31|last",
          "yearly on MM-DD", "every N days|weeks|months|years from YYYY-MM-DD")


class RecurringError(ValidationError):
    """A schedule or recurring item that is not valid."""


def _bad_schedule(text, why=None):
    reason = "invalid schedule %r" % (text,) if why is None else why
    return RecurringError("%s: allowed shapes are %s" % (reason, "; ".join(SHAPES)))


def _is_date(value):
    return isinstance(value, date) and not isinstance(value, datetime)


def _month_date(year, month, day):
    """The day of that month, clamped to its last day."""
    return date(year, month, min(day, calendar.monthrange(year, month)[1]))


@dataclass(frozen=True)
class Schedule:
    """A rhythm of dates.

    ``kind`` is daily, weekly, monthly, yearly or every.  ``weekday`` (0 = Monday) belongs to weekly,
