    ``day`` to monthly (0 means the last day) and yearly, ``month`` to yearly.  An ``every`` schedule
    has ``step`` units of ``unit`` (singular) counted from ``anchor``.
    """

    kind: str
    weekday: Optional[int] = None
    day: Optional[int] = None
    month: Optional[int] = None
    step: Optional[int] = None
    unit: Optional[str] = None
    anchor: Optional[date] = None

    def __str__(self):
        if self.kind == "daily":
            return "daily"
        if self.kind == "weekly":
            return "weekly on %s" % WEEKDAYS[self.weekday]
        if self.kind == "monthly":
            return "monthly on %s" % ("last" if self.day == 0 else self.day)
        if self.kind == "yearly":
            return "yearly on %02d-%02d" % (self.month, self.day)
        unit = self.unit if self.step == 1 else self.unit + "s"
        return "every %d %s from %s" % (self.step, unit, self.anchor.isoformat())

    def between(self, start, end):
        """The schedule's own dates from ``start`` to ``end``, both included, ascending."""
        for value in (start, end):
            if not _is_date(value):
                raise RecurringError("expected a date, not %r" % (value,))
        dates = []
        for day in self.dates_from(start):
            if day > end:
                break
            dates.append(day)
        return dates

    def dates_from(self, start):
        """Generate the schedule's dates on or after ``start``, ascending, up to 9999-12-31."""
        if self.kind == "daily":
            return self._every_days(start, date(1, 1, 1), 1)
        if self.kind == "weekly":
            first = start + timedelta(days=(self.weekday - start.weekday()) % 7) \
                if start <= date.max - timedelta(days=6) else None
            return self._every_days(start, first, 7) if first else iter(())
        if self.kind == "monthly":
            return self._monthly(start)
        if self.kind == "yearly":
            return self._yearly(start)
        if self.unit == "day":
            return self._every_days(start, self.anchor, self.step)
        if self.unit == "week":
            return self._every_days(start, self.anchor, self.step * 7)
        return self._every_months(start, self.step * (12 if self.unit == "year" else 1))

    def _every_days(self, start, anchor, step):
        """Dates ``anchor + k * step`` days (k >= 0) that are on or after ``start``."""
        origin = anchor.toordinal()
        first = max(start.toordinal(), origin)
        k = -((origin - first) // step)
