    def _every_months(self, start, months):
        """Dates ``anchor`` moved forward by ``k * months`` months, each clamped to its month end."""
        anchor = self.anchor
        offset = (start.year - anchor.year) * 12 + start.month - anchor.month
        k = max(0, offset // months - 1)
        while True:
            year, month0 = divmod(anchor.year * 12 + anchor.month - 1 + k * months, 12)
