_NUMBER = re.compile(r"[0-9]+")
_YEARLY = re.compile(r"([0-9]{2})-([0-9]{2})")
_DATE = re.compile(r"([0-9]{4})-([0-9]{2})-([0-9]{2})")


def _schedule_date(word, text):
    match = _DATE.fullmatch(word)
    if not match:
        raise _bad_schedule(text)
    try:
        return date(int(match.group(1)), int(match.group(2)), int(match.group(3)))
    except ValueError:
        raise _bad_schedule(text)


def parse_schedule(text):
    """Read schedule text such as ``monthly on last`` into a :class:`Schedule`."""
    if not isinstance(text, str):
        raise _bad_schedule(text, "schedule must be text, not %r" % (text,))
    if not text.isascii():
        raise _bad_schedule(text)
    words = text.lower().split()
    if words == ["daily"]:
        return Schedule("daily")
    if len(words) == 3 and words[1] == "on":
        kind, value = words[0], words[2]
        if kind == "weekly" and value in WEEKDAYS:
            return Schedule("weekly", weekday=WEEKDAYS.index(value))
        if kind == "monthly" and value == "last":
            return Schedule("monthly", day=0)
        if kind == "monthly" and re.fullmatch(r"[0-9]{1,2}", value) and 1 <= int(value) <= 31:
            return Schedule("monthly", day=int(value))
        match = _YEARLY.fullmatch(value) if kind == "yearly" else None
        if match:
            month, day = int(match.group(1)), int(match.group(2))
            if 1 <= month <= 12 and 1 <= day <= calendar.monthrange(2000, month)[1]:
                return Schedule("yearly", day=day, month=month)
    if len(words) == 5 and words[0] == "every" and words[3] == "from":
        unit = words[2][:-1] if words[2].endswith("s") else words[2]
        if (_NUMBER.fullmatch(words[1]) and len(words[1]) <= MAX_STEP_DIGITS
                and int(words[1]) >= 1 and unit in UNITS):
            return Schedule("every", step=int(words[1]), unit=unit,
                            anchor=_schedule_date(words[4], text))
    raise _bad_schedule(text)


_NAME = re.compile(r"[A-Za-z0-9][A-Za-z0-9_-]*")


class Recurring:
    """A named series: a schedule, a template transaction and the bounds of the series."""

    def __init__(self, name, schedule, template, start, end=None, count=None):
        if not isinstance(name, str) or not _NAME.fullmatch(name):
            raise RecurringError(
                "invalid recurring name %r: use ASCII letters, digits, '-' and '_', "
                "not starting with '-' or '_'" % (name,))
        if isinstance(schedule, str):
            schedule = parse_schedule(schedule)
        elif not isinstance(schedule, Schedule):
            raise RecurringError("schedule must be a Schedule or text, not %r" % (schedule,))
        if not isinstance(template, Transaction):
            raise RecurringError("template must be a Transaction, not %r" % (template,))
        if not _is_date(start):
            raise RecurringError("start must be a date, not %r" % (start,))
        if end is not None:
            if not _is_date(end):
                raise RecurringError("end must be a date, not %r" % (end,))
            if end < start:
                raise RecurringError("end %s is before start %s" % (end.isoformat(), start.isoformat()))
        if count is not None and (type(count) is not int or count < 1):
            raise RecurringError("count must be a whole number of at least 1, not %r" % (count,))
        self.name = name
        self.schedule = schedule
        self.template = template
        self.start = start
        self.end = end
        self.count = count

    def _key(self):
        return (self.name, self.schedule, self.template, self.start, self.end, self.count)

    def __eq__(self, other):
        return isinstance(other, Recurring) and self._key() == other._key()

    def __ne__(self, other):
        return not self == other

    __hash__ = None

    def __repr__(self):
        return "Recurring(%r, %r, %r, start=%r, end=%r, count=%r)" % (
            self.name, str(self.schedule), self.template, self.start, self.end, self.count)


def _check_dates(*values):
    for value in values:
        if not _is_date(value):
            raise RecurringError("expected a date, not %r" % (value,))


def _series(rec, start):
    """The series' dates on or after ``start`` (and on or after ``rec.start``), ascending."""
    if rec.count is None:
        generator = rec.schedule.dates_from(max(start, rec.start))
    else:
        generator = islice(rec.schedule.dates_from(rec.start), rec.count)
    for day in generator:
        if rec.end is not None and day > rec.end:
            return
        if day >= start:
            yield day


def occurrences(rec, start, end):
    """The dates of the series inside the window ``start``..``end``, both included."""
    _check_dates(start, end)
    dates = []
    for day in _series(rec, start):
        if day > end:
            break
        dates.append(day)
    return dates


def next_occurrence(rec, after):
    """The first date of the series strictly after ``after``, or None."""
    _check_dates(after)
    if after == date.max:
        return None
    return next(_series(rec, after + timedelta(days=1)), None)


def instantiate(rec, on):
    """The copy of the template dated ``on``."""
    _check_dates(on)
    template = rec.template
    return Transaction(
        date=on,
        payee=template.payee,
        narration=template.narration,
        postings=list(template.postings),
        tags=tuple(sorted(set(template.tags) | {"recurring"})),
        flag=template.flag,
        id=None,
    )


def expand(recs, start, end):
    """Copies of every item's template for every date in the window, ordered by date, name, position."""
    _check_dates(start, end)
    found = []
    for position, rec in enumerate(recs):
        for day in occurrences(rec, start, end):
            found.append((day, rec.name, position, rec))
    found.sort(key=lambda item: item[:3])
    return [instantiate(rec, day) for day, _, _, rec in found]


def _ordinal(number):
    if 11 <= number % 100 <= 13:
        return "%dth" % number
    return "%d%s" % (number, {1: "st", 2: "nd", 3: "rd"}.get(number % 10, "th"))


def describe(schedule):
    """Say a schedule in words for a person."""
    if isinstance(schedule, str):
        schedule = parse_schedule(schedule)
    if not isinstance(schedule, Schedule):
        raise RecurringError("expected a Schedule, not %r" % (schedule,))
    if schedule.kind == "daily":
        return "every day"
    if schedule.kind == "weekly":
        return "every %s" % WEEKDAY_NAMES[schedule.weekday]
    if schedule.kind == "monthly":
        if schedule.day == 0:
            return "on the last day of every month"
        return "on the %s of every month" % _ordinal(schedule.day)
    if schedule.kind == "yearly":
        return "every year on %d %s" % (schedule.day, MONTH_NAMES[schedule.month - 1])
    every = "every %s" % schedule.unit if schedule.step == 1 else "every %d %ss" % (
        schedule.step, schedule.unit)
    return "%s from %s" % (every, schedule.anchor.isoformat())

